//! The Muse Session Protocol (MSP) v1 wire schema, typed.
//!
//! Generated by hand from `fixtures/msp/msp-ts/msp.d.ts` (muse 1.1.1) and validated against the
//! live wire captures in `fixtures/msp/*.jsonl`. Every `export interface` and `export type` of the
//! published declarations has a counterpart here under the same name.
//!
//! # Conventions
//!
//! * Every struct is `#[serde(rename_all = "camelCase")]`; Rust fields are snake_case and the
//!   camelCase wire names are produced by serde.
//! * **Open** string unions (the ones msp.d.ts spells `… | (string & {})`) are unit enums with a
//!   final `Unknown` variant, so a value a newer server invents deserializes instead of failing.
//!   `as_wire()` returns the wire string, or `None` for `Unknown` — *serializing* `Unknown` cannot
//!   recover the original string and is a bug in the caller.
//! * **Closed** unions ([`AccountLoginType`], [`ApprovalMode`], [`HistoryPreference`], [`IfBusy`],
//!   [`ReasoningEffort`], [`TurnInputPartType`], [`UserInputSelectionMode`], [`ViewPageDirection`],
//!   [`PlatformFamily`], [`PlatformOs`], [`CommandAckStatus`], [`JsonRpcVersion`],
//!   [`ItemReadOutputEncoding`]) have no `Unknown`: an unrecognized
//!   value there is a real error and is reported as one.
//! * Optional members are `Option<T>` that skip serialization when `None`. **Required-nullable**
//!   members (present on the wire, `null` when empty) are `Option<T>` that serialize as `null`.
//!
//! # What the binary emits that the published index omits
//!
//! [`MSP_METHODS`] and [`MSP_NOTIFICATIONS`] are the SS1.9 index verbatim. The muse 1.1.1 binary
//! additionally emits two things that index does not list, and a client must handle both:
//!
//! * the **`session/started` notification**, params `{"session": Session}` — modelled as
//!   [`SessionStartedParams`]. It arrives right after a `session/start` result.
//! * the **`userInput/request` and `approval/request` server→client *requests*** (not
//!   notifications: they carry an `id` in the server's own id space). Their params are exactly
//!   [`UserInputRequestParams`] and [`ApprovalRequestParams`], the same objects the
//!   `userInput/requested` / `approval/requested` notifications carry.
//!
//! # Where the wire contradicts msp.d.ts
//!
//! Five members msp.d.ts declares optional are, in the captures, always present and sometimes
//! explicitly `null` — they are modelled here as required-nullable so a re-serialized frame is
//! equal to what the server sent: [`Item::turn_id`], [`SessionTokenUsageParams::model_id`],
//! [`SessionBranchChangedParams::branch`], [`SessionModelChangedParams::provider_id`] and
//! [`SessionGoalChangedParams::goal`].

use serde::{Deserialize, Serialize};
use serde_json::{Map, Value};

/// Deserializer for an optional-**and**-nullable member, so that "key absent" and
/// "key present, `null`" stay distinguishable through a round trip.
fn double_option<'de, T, D>(de: D) -> Result<Option<Option<T>>, D::Error>
where
    T: Deserialize<'de>,
    D: serde::Deserializer<'de>,
{
    Option::<T>::deserialize(de).map(Some)
}

/// Declares an **open** string enum: unknown server values fold to `Unknown`, deliberately, because
/// the schema declares the domain open and a new value is additive evolution, not an error.
macro_rules! open_enum {
    (
        $(#[$outer:meta])*
        $name:ident { $( $variant:ident = $wire:literal ),* $(,)? }
    ) => {
        $(#[$outer])*
        ///
        /// **Open enum.** A value this build does not know deserializes to `Unknown` rather than
        /// failing — that is deliberate: the schema declares this domain open. Use
        /// [`Self::as_wire`] for the wire string; serializing `Unknown` cannot recover the value
        /// the server actually sent and is a caller bug.
        #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
        #[serde(rename_all = "camelCase")]
        pub enum $name {
            $(
                #[doc = concat!("The `", $wire, "` value.")]
                #[serde(rename = $wire)]
                $variant,
            )*
            /// A value outside this build's vocabulary — render it generically, never as an error.
            #[serde(other)]
            Unknown,
        }

        impl $name {
            /// The wire string for this variant, or `None` for [`Self::Unknown`] (whose original
            /// string was not retained).
            #[must_use]
            pub fn as_wire(&self) -> Option<&'static str> {
                match self {
                    $( Self::$variant => Some($wire), )*
                    Self::Unknown => None,
                }
            }
        }
    };
}

/// Declares a **closed** string enum: an unrecognized value is a real error and fails to decode.
macro_rules! closed_enum {
    (
        $(#[$outer:meta])*
        $name:ident { $( $variant:ident = $wire:literal ),* $(,)? }
    ) => {
        $(#[$outer])*
        ///
        /// **Closed enum.** An unrecognized value is a protocol error and fails to deserialize.
        #[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
        #[serde(rename_all = "camelCase")]
        pub enum $name {
            $(
                #[doc = concat!("The `", $wire, "` value.")]
                #[serde(rename = $wire)]
                $variant,
            )*
        }

        impl $name {
            /// The wire string for this variant.
            #[must_use]
            pub fn as_wire(&self) -> &'static str {
                match self {
                    $( Self::$variant => $wire, )*
                }
            }
        }
    };
}

// ---------------------------------------------------------------------------------------------
// Account (experimental)
// ---------------------------------------------------------------------------------------------

/// The one account payload shape: the `account/read` result and the
/// `account/changed` params.
///
/// Every `account/*` method is gated on `initialize.capabilities.
/// experimentalApi: true`; without the opt-in each one answers `-32601`
/// with `data.kind: "experimentalRequired"`. `label` is a display string
/// that never carries key material, and is omitted — never `null` — when
/// absent.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountState {
    /// `false` exactly when the effective provider endpoint needs no caller
    /// credential (keyless/gateway deployments), so those clients never nag
    /// the user to sign in.
    pub credential_required: bool,
    /// Display label for the credential in effect, when the server sends one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub label: Option<String>,
    /// Which credential lane is in effect.
    pub state: AccountStateKind,
}

open_enum! {
    /// Which credential lane is in effect. Server-produced, so the
    /// vocabulary is open: a future lane projects additively.
    AccountStateKind {
        LoggedOut = "loggedOut",
        EnvKey = "envKey",
        ApiKey = "apiKey",
        AccountLogin = "accountLogin",
    }
}

closed_enum! {
    /// Which login flow `account/loginStart` runs. Client-produced, so the
    /// vocabulary is closed: an unknown `type` is an invalid-params error.
    AccountLoginType {
        DeviceCode = "deviceCode",
        ApiKey = "apiKey",
    }
}

/// `account/loginStart` params: `{type, apiKey?}`.
///
/// `apiKey` is required non-empty for the `apiKey` type and forbidden for
/// the `deviceCode` type; both violations are invalid-params errors. `Debug`
/// is hand-written: the derive would print the raw key bytes into any
/// `{:?}` context, and the key must never reach a log.
#[derive(Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountLoginStartParams {
    /// The API key to store (the `apiKey` type only). The only
    /// secret-bearing member of the account surface.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub api_key: Option<String>,
    /// Which flow to run.
    #[serde(rename = "type")]
    pub r#type: AccountLoginType,
}

impl std::fmt::Debug for AccountLoginStartParams {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("AccountLoginStartParams")
            .field("type", &self.r#type)
            .field("apiKey", &"<redacted>")
            .finish()
    }
}

/// `account/loginStart` result: `{verificationUrl?, userCode?}` — both
/// present for a started device-code flow, both absent for the synchronous
/// `apiKey` type. The device-code artifacts travel only here, to the
/// requesting connection; completion notifications never carry them.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountLoginStartResult {
    /// The code the user confirms or enters at the verification URL
    /// (device-code flow only).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub user_code: Option<String>,
    /// Where the user signs in (device-code flow only).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub verification_url: Option<String>,
}

open_enum! {
    /// How a login flow ended. Server-produced, so the vocabulary is open:
    /// a future flow may end in a new way additively.
    AccountLoginOutcome {
        Granted = "granted",
        Denied = "denied",
        Expired = "expired",
        Cancelled = "cancelled",
        Failed = "failed",
    }
}

/// `account/loginCompleted` params: `{outcome, message?}`. `message` is a
/// display string for the `denied` / `expired` / `failed` outcomes only —
/// never key material.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountLoginCompletedParams {
    /// Display message, on the non-granting outcomes only.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub message: Option<String>,
    /// How the flow ended.
    pub outcome: AccountLoginOutcome,
}

/// `account/loginCancel` result: `{cancelled}` — `true` iff a pending flow
/// existed and was cancelled.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AccountLoginCancelResult {
    /// Whether a pending flow was cancelled.
    pub cancelled: bool,
}

