// Messages, models, notifications, outputs (SS3.8, SS3.10, SS4.5.5)
// ---------------------------------------------------------------------------------------------

/// `userMessage` image attachment metadata (tdd SS4.5.2): metadata only — the durable bytes live in
/// the log and are reachable on the raw altitude.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct MessageAttachment {
    /// Pixel height, when known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub height: Option<u32>,
    /// The image media type (e.g. `"image/png"`).
    pub media_type: String,
    /// Attachment type, `"image"` in v1 (free string: the vocabulary grows additively).
    #[serde(rename = "type")]
    pub r#type: String,
    /// Pixel width, when known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<u32>,
}

/// One visible catalog row (tdd SS3.10). Catalog rows marked hidden never reach the wire, so a
/// client cannot select one.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelCatalogEntry {
    /// Context limit; `null` when the catalog source declared nothing. Required-nullable.
    #[serde(default)]
    pub context_limit: Option<u64>,
    /// Cost block; `null` when the catalog source declared nothing. Required-nullable.
    #[serde(default)]
    pub cost: Option<ModelCost>,
    /// Description; `null` when the catalog source declared nothing. Required-nullable.
    #[serde(default)]
    pub description: Option<String>,
    /// Presentation label.
    pub display_label: String,
    /// Marks the session's effective model when `sessionId` was supplied. May be false for every
    /// row — a client MUST NOT assume exactly one.
    pub is_active: bool,
    /// Marks the catalog's default row. May be false for every row.
    pub is_default: bool,
    /// The selectable model id.
    pub model_id: String,
    /// Output limit; `null` when the catalog source declared nothing. Required-nullable.
    #[serde(default)]
    pub output_limit: Option<u64>,
    /// Provider profile; `null` when the catalog source declared nothing. Required-nullable.
    #[serde(default)]
    pub profile_id: Option<String>,
    /// Provider routing.
    pub provider_id: String,
    /// Release date; `null` when the catalog source declared nothing. Required-nullable.
    #[serde(default)]
    pub release_date: Option<String>,
}

open_enum! {
    /// Where a model catalog came from (tdd SS3.10) — how a client tells a live provider catalog
    /// from a test fake and labels it honestly.
    ModelCatalogSource {
        ProviderCatalog = "providerCatalog",
        FakeCatalog = "fakeCatalog",
        UnresolvedCatalog = "unresolvedCatalog",
        BundledCatalog = "bundledCatalog",
        ConfigCatalog = "configCatalog",
    }
}

open_enum! {
    /// What drove a model selection (tdd SS4.6.1).
    ModelChangeSource {
        User = "user",
        Default = "default",
        Policy = "policy",
    }
}

/// Per-1M-token catalog cost, carried **verbatim** for display and never rounded or re-formatted by
/// the host (tdd SS3.10). Cost arithmetic stays client-local view math.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelCost {
    /// Cached-input cost, a decimal string.
    pub cached: String,
    /// Currency; nullable — today's catalogs are USD. Required-nullable.
    #[serde(default)]
    pub currency: Option<String>,
    /// Input cost, a decimal string.
    pub input: String,
    /// Output cost, a decimal string.
    pub output: String,
}

/// `model/list` params (tdd SS3.10): the discovery half of the model-picker gesture. **A query, not
/// a command** — no `commandId`, no durable intake record, no view event.
#[derive(Clone, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelListParams {
    /// When present, the row matching that session's effective model is flagged `isActive`. When
    /// absent, no row is active — a client may list before it has a session.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub session_id: Option<String>,
}

/// `model/list` result (tdd SS3.10). A snapshot at call time: v1 has no catalog subscription.
/// `models` MAY be empty — a build shipped with no bundled models is a supported configuration.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelListResult {
    /// Visible rows only, newest `releaseDate` first.
    pub models: Vec<ModelCatalogEntry>,
    /// The catalog's profile; `null` when none. Required-nullable.
    #[serde(default)]
    pub profile_id: Option<String>,
    /// The catalog's provider.
    pub provider_id: String,
    /// Where the catalog came from.
    pub source: ModelCatalogSource,
}

/// A model selection (tdd SS3.8). Empty strings are normalized to absent.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelSelection {
    /// Presentation label.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub display_label: Option<String>,
    /// Catalog model id. Required.
    pub model_id: String,
    /// Provider profile. Omitted and explicit `null` both mean "no profile".
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub profile_id: Option<String>,
    /// Provider routing.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub provider_id: Option<String>,
}

/// Rich content the model saw beyond text (tdd SS4.5.5): metadata only — fetch bytes via
/// `item/readOutput` when an `outputRef` exists.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ModelVisibleContent {
    /// Pixel height, when known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub height: Option<u32>,
    /// The content media type.
    pub media_type: String,
    /// The recorded content path.
    pub path: String,
    /// The tool that produced the content.
    pub source_tool_name: String,
    /// Content type, `"image"` in v1 (free string, grows with the durable vocabulary).
    #[serde(rename = "type")]
    pub r#type: String,
    /// Pixel width, when known.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub width: Option<u32>,
}

/// A notification frame, either direction (SS1.2 §2.2). No `id`; a notification is never answered.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Notification {
    /// Emission time in Unix milliseconds, recorded once at emission; server→client notifications
    /// only. Optional on the wire so decoders tolerate older servers.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub emitted_at_ms: Option<u64>,
    /// The literal `"2.0"`.
    pub jsonrpc: JsonRpcVersion,
    /// Notification method name.
    pub method: String,
    /// Method-specific parameters; omitted entirely when empty.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub params: Option<Map<String, Value>>,
}

/// Stored-output reference (tdd SS4.5.5). The fetch path is `item/readOutput`.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct OutputRef {
    /// Whether the bytes are servable.
    pub availability: OutputRefAvailability,
    /// Stored byte length.
    pub byte_len: u64,
    /// Content digest (e.g. `"sha256:..."`), when recorded.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub digest: Option<String>,
    /// The stored output's durable id.
    pub id: String,
    /// The stored output's kind, verbatim durable vocabulary (e.g. `"tool_output"`; snake_case per
    /// the SS1.6 casing exemption).
    pub kind: String,
    /// Media type, when recorded.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub media_type: Option<String>,
    /// Stored path, when recorded.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub path: Option<String>,
    /// The stored output's URI.
    pub uri: String,
}

open_enum! {
    /// Whether a stored output's bytes are servable (tdd SS4.5.5).
    OutputRefAvailability {
        Available = "available",
        Missing = "missing",
        Unsupported = "unsupported",
        AccessFailed = "accessFailed",
    }
}

closed_enum! {
    /// The `item/readOutput` content encoding (tdd SS4.7.4). Closed: text media is ALWAYS `utf8`
    /// and binary media `base64`; a third value would change the client's decode contract.
    ItemReadOutputEncoding {
        Utf8 = "utf8",
        Base64 = "base64",
    }
}

/// `item/readOutput` params (tdd SS4.7.4): byte-ranged fetch of stored full output that the view
/// truncated. Read-only; works on loaded and unloaded sessions; no lease.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ItemReadOutputParams {
    /// The item whose stored output is fetched.
    pub item_id: String,
    /// STORED bytes requested; default and max 6 MiB. A value above the max is served at the max.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub length_bytes: Option<u64>,
    /// STORED-byte offset to start from; 0 when omitted. STORED bytes are a property of the
    /// output, not of a transport.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub offset_bytes: Option<u64>,
    /// The `outputRef.id` from the item (never the `uri`; the uri is display/provenance).
    pub output_ref: String,
    /// The session the item belongs to.
    pub session_id: String,
}

/// `item/readOutput` result (tdd SS4.7.4): one stored-byte page.
#[derive(Clone, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ItemReadOutputResult {
    /// STORED bytes served in THIS response (not the output's total; that is `outputRef.byteLen`
    /// on the item). The next page's `offsetBytes` is `offsetBytes + byteLen`.
    pub byte_len: u64,
    /// The served range, decoded per `encoding`.
    pub content: String,
    /// How `content` encodes the stored bytes.
    pub encoding: ItemReadOutputEncoding,
    /// `true` when this range reached the end of the stored output.
    pub eof: bool,
    /// The stored output's media type (e.g. `text/plain`).
    pub media_type: String,
    /// The STORED-byte offset this response actually served from.
    pub offset_bytes: u64,
}

